def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    value = new - old
    return {
        "value": value,
        "trace": {
            "old_percentage": old,
            "new_percentage": new,
            "difference": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
